examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
    MonarchTreeView(
        items = departments,
        expanded = expanded,
        onExpandedChange = { expanded = it },
        expandIcon = {
            MonarchIcon(
                imageVector = SampleIcons.ChevronRight,
                contentDescription = null,
                size = MonarchIconSize.Sm,
            )
        },
        modifier = Modifier.height(440.dp).semantics { contentDescription = {{label}} },
        selected = selected,
        onSelectedChange = { selected = it },
        meta = { item ->
            MonarchIconButton(label = "${{{editLabel}}} ${item.label}", onClick = {}, size = MonarchButtonSize.Sm) {
                MonarchIcon(SampleIcons.Pencil, contentDescription = null)
            }
        },
    )
    MonarchText(text = "Selected: " + selected.joinToString())
}

examples.setupTemplate:
val departments = remember {
    listOf(
        MonarchTreeViewItem(id = {{items.0.id}}, label = {{items.0.label}}, description = {{items.0.description}}, children = listOf(
            MonarchTreeViewItem(id = {{items.0.children.0.id}}, label = {{items.0.children.0.label}}, description = {{items.0.children.0.description}}, children = emptyList()),
            MonarchTreeViewItem(id = {{items.0.children.1.id}}, label = {{items.0.children.1.label}}, description = {{items.0.children.1.description}}),
            MonarchTreeViewItem(id = {{items.0.children.2.id}}, label = {{items.0.children.2.label}}, description = {{items.0.children.2.description}}, children = listOf(
                MonarchTreeViewItem(id = {{items.0.children.2.children.0.id}}, label = {{items.0.children.2.children.0.label}}, description = {{items.0.children.2.children.0.description}}),
                MonarchTreeViewItem(id = {{items.0.children.2.children.1.id}}, label = {{items.0.children.2.children.1.label}}, description = {{items.0.children.2.children.1.description}}),
            )),
        )),
        MonarchTreeViewItem(id = {{items.1.id}}, label = {{items.1.label}}, description = {{items.1.description}}, children = listOf(
            MonarchTreeViewItem(id = {{items.1.children.0.id}}, label = {{items.1.children.0.label}}, description = {{items.1.children.0.description}}),
            MonarchTreeViewItem(id = {{items.1.children.1.id}}, label = {{items.1.children.1.label}}, description = {{items.1.children.1.description}}),
        )),
    )
}
var expanded by remember { mutableStateOf(setOf({{expanded.0}}, {{expanded.1}})) }
var selected by remember { mutableStateOf(setOf({{selected.0}})) }

examples.setup:
val departments = remember {
    listOf(
        MonarchTreeViewItem(id = "ops", label = "Operations", description = "Business unit · 42 people", children = listOf(
            MonarchTreeViewItem(id = "finance", label = "Finance", description = "Department · 12 people", children = emptyList()),
            MonarchTreeViewItem(id = "legal", label = "Legal", description = "Department · 4 people"),
            MonarchTreeViewItem(id = "facilities", label = "Facilities", description = "Division · 26 people", children = listOf(
                MonarchTreeViewItem(id = "workplace", label = "Workplace", description = "Department · 18 people"),
                MonarchTreeViewItem(id = "security", label = "Security", description = "Department · 8 people"),
            )),
        )),
        MonarchTreeViewItem(id = "product", label = "Product", description = "Business unit · 64 people", children = listOf(
            MonarchTreeViewItem(id = "design", label = "Design", description = "Department · 14 people"),
            MonarchTreeViewItem(id = "eng", label = "Engineering", description = "Department · 50 people"),
        )),
    )
}
var expanded by remember { mutableStateOf(setOf("ops", "product")) }
var selected by remember { mutableStateOf(setOf("eng")) }

